CREATE TABLE public.contact_inquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL, company text, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.contact_inquiries TO anon, authenticated;
GRANT ALL ON public.contact_inquiries TO service_role;
ALTER TABLE public.contact_inquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Visitors may submit contact inquiries" ON public.contact_inquiries FOR INSERT TO anon, authenticated WITH CHECK (length(trim(name)) BETWEEN 1 AND 120 AND length(trim(email)) BETWEEN 3 AND 255 AND length(trim(message)) BETWEEN 1 AND 3000);
CREATE TABLE public.payment_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, plan text NOT NULL CHECK (plan IN ('PRO','PLUS','ULTRA')), amount_paise integer NOT NULL CHECK (amount_paise > 0), order_id text UNIQUE, transaction_id text UNIQUE, payment_status text NOT NULL DEFAULT 'created' CHECK (payment_status IN ('created','paid','failed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.payment_records TO service_role;
ALTER TABLE public.payment_records ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
CREATE TRIGGER contact_inquiries_updated_at BEFORE UPDATE ON public.contact_inquiries FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER payment_records_updated_at BEFORE UPDATE ON public.payment_records FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();